<template><div class="reports-page"><div class="page-head"><div><div class="eyebrow">数据分析</div><h2>投放统计</h2><p>点击数据行逐级查看 Campaign、AdSet 和广告。</p></div><el-button :disabled="!parentStack.length" @click="goBack">返回上级</el-button></div><el-card shadow="never" class="filters"><el-select v-model="accountId" placeholder="选择广告账户" filterable @change="resetAndLoad"><el-option v-for="account in accounts" :key="account.id" :label="account.account_name || account.account_id" :value="account.id" /></el-select><el-select v-model="days" @change="loadBreakdown"><el-option label="近 7 天" :value="7"/><el-option label="近 30 天" :value="30"/><el-option label="近 90 天" :value="90"/></el-select></el-card><el-alert v-if="error" :title="error" type="warning" :closable="false"/><el-empty v-if="!accountId" description="请选择广告账户"/><el-card v-else shadow="never"><template #header>{{ levelLabel }}统计</template><el-table v-loading="loading" :data="items" stripe @row-click="drill"><el-table-column label="名称 / Meta ID" min-width="280"><template #default="scope"><div>{{ scope.row.entity_name }}</div><small>{{ scope.row.entity_id }}</small></template></el-table-column><el-table-column prop="spend" label="花费"/><el-table-column prop="impressions" label="展示"/><el-table-column prop="clicks" label="点击"/><el-table-column prop="conversions" label="转化"/><el-table-column prop="conversion_rate" label="转化率"><template #default="scope">{{ Number(scope.row.conversion_rate || 0).toFixed(2) }}%</template></el-table-column><el-table-column prop="cpa" label="CPA"/><el-table-column prop="roas" label="ROAS"/></el-table></el-card></div></template>
<script setup lang="ts">import { computed,onMounted,ref } from 'vue';import request from '@/utils/request';import { accountApi } from '@/api/admin';const accounts=ref<any[]>([]),accountId=ref(''),days=ref(30),level=ref('account'),parentId=ref(''),items=ref<any[]>([]),parentStack=ref<any[]>([]),loading=ref(false),error=ref('');const levelLabel=computed(()=>({account:'账号',campaign:'Campaign',adset:'AdSet',ad:'广告'}[level.value]||level.value));const nextLevel:any={account:'campaign',campaign:'adset',adset:'ad'};async function loadAccounts(){try{const {data}=await accountApi.list({page:1,page_size:100});accounts.value=data||[];if(!accountId.value&&accounts.value.length)accountId.value=accounts.value[0].id}catch{accounts.value=[]}}async function loadBreakdown(){if(!accountId.value)return;loading.value=true;error.value='';try{const {data}=await request.get('/api/v1/reports/breakdown',{params:{dimension:level.value,days:days.value,parent_id:parentId.value||accountId.value}});items.value=data.items||[]}catch{items.value=[];error.value='统计加载失败，请检查权限或同步状态'}finally{loading.value=false}}function resetAndLoad(){level.value='account';parentId.value='';parentStack.value=[];loadBreakdown()}function drill(row:any){const next=nextLevel[level.value];if(!next)return;parentStack.value.push({level:level.value,parentId:parentId.value});level.value=next;parentId.value=row.entity_id;loadBreakdown()}function goBack(){const previous=parentStack.value.pop();if(!previous)return;level.value=previous.level;parentId.value=previous.parentId;loadBreakdown()}onMounted(async()=>{await loadAccounts();await loadBreakdown()})</script>
<style scoped>.reports-page{padding:4px}.page-head{display:flex;justify-content:space-between;margin-bottom:18px}.eyebrow{color:#829ab1;font-size:12px}.page-head h2{margin:6px 0;color:#102a43}.page-head p{margin:0;color:#627d98;font-size:13px}.filters{display:flex;gap:12px;margin-bottom:16px}.filters .el-select{width:220px}small{color:#9aaabd;font-size:11px;cursor:pointer}.el-table{cursor:pointer}</style>
